    if uid is None:
        continue
    uid = str(uid)
    status = pick(o, ['status', 'state'])
    if uid in users and status == 'paid':
        val = pick(o, ['total', 'amount', 'price', 'total_price', 'sum'])
        if val is not None:
            totals[uid] += float(val)

